  attempt.flowId = null;
  attempt.agentPath = null;
  attempt.conversationId = null;

  /* No scan entries and no runtime host: the files read owns recovery. */
  expect(reconcileEmbeddedReviewFlows([parent], [flow], "2026-07-22T01:00:00.000Z")).toBe(true);
