test("onExhausted is validated and edited with the fail edge, and freezes with it (#1868)", async () => {
  const h = harness();
  const { ports } = h;
  savePipelines([]);
  const refused = await createPipelineFromRequest({
    task: "Bad option",
    repoDir: "/repo",
    stages: BUDGET_STAGES({ to: "build", maxRounds: 2, onExhausted: "stop" }) as never,
    autoStart: false,
  }, ports);
  expect(refused.error).toContain("onExhausted");
  const created = await createPipelineFromRequest({
    task: "Edge option",
    repoDir: "/repo",
    stages: BUDGET_STAGES({ to: "build", maxRounds: 2 }) as never,
    autoStart: false,
  }, ports);
  const id = created.pipeline!.id;
  expect(created.pipeline!.stages[1]!.onFail).toEqual({ to: "build", maxRounds: 2 });
  expect((await patchPipeline(id, { action: "set-edge", stageId: "critique", edge: "fail", to: "build", onExhausted: "stop" as never }, ports)).status).toBe(400);
  expect((await patchPipeline(id, { action: "set-edge", stageId: "critique", edge: "pass", to: "ship", onExhausted: "park" }, ports)).status).toBe(400);
  const parked = await patchPipeline(id, { action: "set-edge", stageId: "critique", edge: "fail", to: "build", maxRounds: 3, onExhausted: "park" }, ports);
  expect(parked.pipeline?.stages[1]?.onFail).toEqual({ to: "build", maxRounds: 3, onExhausted: "park" });
  const advance = await patchPipeline(id, { action: "set-edge", stageId: "critique", edge: "fail", to: "build", maxRounds: 3, onExhausted: "advance" }, ports);
  expect(advance.pipeline?.stages[1]?.onFail).toEqual({ to: "build", maxRounds: 3, onExhausted: "advance" });

  /* The handoff is a traversal of the edge, so it freezes the edge's option
     with the rest of it. */
  await patchPipeline(id, { action: "set-edge", stageId: "critique", edge: "fail", to: "build", maxRounds: 1, onExhausted: "advance" }, ports);
  await patchPipeline(id, { action: "start" }, ports);
  await tickPipelines([], ports);
  await failEveryCritique(h, 1);
  const handedOff = loadPipelines()[0]!;
  expect(handedOff.runs.find((run) => run.stageId === "critique")!.attempts[0]!.budgetSpent).toBe(true);
  const frozen = await patchPipeline(id, { action: "set-edge", stageId: "critique", edge: "fail", to: "build", maxRounds: 1, onExhausted: "park" }, ports);
  expect(frozen.status).toBe(409);
  expect(frozen.error).toContain("frozen evidence");
  expect(loadPipelines()[0]!.stages[1]!.onFail).toEqual({ to: "build", maxRounds: 1, onExhausted: "advance" });
});

/* A spent review budget whose last fix wrote a NEW head, on an edge that asked
   for `stop-after-fix` (#1938, #2187): the lane ends in needs_review, never
   completed, and never takes the reviewer's pass edge for a head nobody
   reviewed. continue-review grants explicit extra rounds and reviews the
   current head in the same pipeline. Under the default the lane completes
   instead (below). */
const STOP_AFTER_FIX = { onExhausted: "stop-after-fix" } as const;
const REVIEW_HEADS = ["1".repeat(40), "2".repeat(40), "3".repeat(40), "4".repeat(40), "5".repeat(40), "6".repeat(40)];

/** The harness with a worktree HEAD the test moves: each build round `n`
    commits REVIEW_HEADS[n - 1] unless `heads` says otherwise. */
function movingHeadHarness(heads: (round: number) => string = (round) => REVIEW_HEADS[round - 1]!) {
  const h = harness();
  let head = ORIGIN_MAIN_SHA;
  let builds = 0;
  const baseExec = h.ports.exec;
  h.ports.exec = (command, rawArgs, ...rest) => {
    const args = command === "timeout" ? rawArgs.slice(rawArgs.indexOf("git") + 1) : rawArgs;
    if (args[0] === "rev-parse" && args[1] === "HEAD") return { code: 0, stdout: `${head}\n`, stderr: "" };
    return baseExec(command, rawArgs, ...rest);
  };
  const beforeBuildPass = () => { builds += 1; head = heads(builds); };
  return Object.assign(h, { beforeBuildPass });
}

async function critiqueRound(h: ReturnType<typeof movingHeadHarness>, status: "pass" | "fail", label: string): Promise<void> {
  await tickPipelines([], h.ports);
  const current = loadPipelines()[0]!;
  const critique = current.runs.find((run) => run.stageId === "critique")!.attempts.at(-1)!;
  h.messages.set(critique.agentPath!, {
    text: `${label}\n\n\`\`\`json\n{"status":"${status}"${status === "fail" ? `,"findings":["P1 ${label}"]` : ""}}\n\`\`\``,
    ts: Date.now() + 100_000_000,
  });
  await tickPipelines([entry(critique.agentPath!)], h.ports);
}

async function buildRound(h: ReturnType<typeof movingHeadHarness>, label: string): Promise<void> {
  await tickPipelines([], h.ports);
  const current = loadPipelines()[0]!;
  const build = current.runs.find((run) => run.stageId === "build")!.attempts.at(-1)!;
  h.beforeBuildPass();
  await tickPipelines([h.finish(build.agentPath!, "pass", label)], h.ports);
}

/** Historical parks stay actionable until a controller cycle migrates them. */
function seedTerminalPark(pipeline: Pipeline, decision = false): Pipeline {
  const spent = pipeline.reviewBudgetSpent;
  if (!spent) return pipeline;
  const review = pipeline.runs.find(run => run.stageId === spent.stageId)!.attempts.find(attempt => attempt.n === spent.attempt)!;
  const activation = review.activatedBy!;
  pipeline.state = "needs_decision"; pipeline.closedAt = null; pipeline.pausedState = null;
  pipeline.cursor = { stageId: spent.stageId, state: "running", input: review.input, activatedBy: activation };
  if (decision) { review.state = "needs_decision"; review.verdict!.status = "needs_decision"; review.decisionRequested = true; }
  pipeline.reviewPending = { terminalRecheck: true, stageId: spent.stageId, attempt: review.n, fixStageId: activation.stageId, fixAttempt: activation.attempt, reviewedHead: pipeline.lastPassedCommit, currentHead: pipeline.lastPassedCommit, verdict: review.verdict!.status, findings: spent.findings, at: review.completedAt! };
  pipeline.stateDetail = `budget spent: ${spent.findings} findings left; its rounds cannot increase`;
  delete pipeline.reviewBudgetSpent;
  if (pipeline.delivery?.disposition === "owner") { pipeline.delivery.active = true; pipeline.delivery.publish = "enabled"; delete pipeline.delivery.releasedAt; }
  savePipelines([pipeline]);
  return pipeline;
}

function continueReview(pipeline: Pipeline, clientRequestId: string, addRounds: unknown, expectedRevision = pipelineRevision(pipeline)) {
  return patchPipeline(pipeline.id, { action: "continue-review", clientRequestId, addRounds: addRounds as number, expectedRevision }, movingHeadPorts!);
}

/** A pre-policy stored grant and its cursor, restored without granting rounds
    through today's API. Exercises historical routing and receipt replay. */
async function restoreHistoricReviewGrant(
  pipeline: Pipeline, clientRequestId: string, rounds: unknown, expectedRevision = pipelineRevision(pipeline),
  actor: import("@/lib/pauseResumeActor").PauseResumeActor = { kind: "operator" },
) {
  const current = loadPipelines().find(lane => lane.id === pipeline.id)!;
  if (!Number.isSafeInteger(rounds) || (rounds as number) < 1 || (rounds as number) > 9
    || current.reviewGrants?.some(grant => grant.clientRequestId === clientRequestId)
    || pipelineRevision(current) !== expectedRevision || !current.reviewPending) {
    return patchPipeline(pipeline.id, { action: "continue-review", clientRequestId, addRounds: rounds as number, expectedRevision }, movingHeadPorts!, actor);
  }
  const pending = current.reviewPending;
  const review = current.stages.find(stage => stage.id === pending.stageId)!;
  const failed = pending.terminalRecheck
    ? current.runs.find(run => run.stageId === pending.stageId)!.attempts.find(attempt => attempt.n === pending.attempt) : null;
  const fix = current.runs.find(run => run.stageId === pending.fixStageId)!.attempts.find(attempt => attempt.n === pending.fixAttempt)!;
  const grant: import("./types").PipelineReviewGrant = { clientRequestId, expectedRevision, stageId: review.id,
    ...(failed ? { terminalAttempt: failed.n } : {}), rounds: rounds as number,
    reviewedHead: pending.reviewedHead, currentHead: pending.currentHead, actor, at: movingHeadPorts!.now() };
  current.reviewGrants = [...(current.reviewGrants ?? []), grant];
  delete current.reviewPending;
  if (failed) {
    if (rounds === 1) failed.budgetSpent = true;
    current.cursor = { stageId: review.onFail!.to, state: "pending",
      input: failed.verdict!.findings?.join("\n") ?? null,
      activatedBy: { stageId: review.id, attempt: failed.n, edge: "fail", ...(rounds === 1 ? { budgetSpent: true as const } : {}) } };
  } else {
    current.cursor = { stageId: review.id, state: "pending", input: fix.output ?? null,
      activatedBy: { stageId: pending.fixStageId, attempt: fix.n, edge: "pass" } };
  }
  current.state = "running"; current.pausedState = null; current.stateDetail = null;
  savePipelines([current]);
  return { pipeline: loadPipelines()[0]!, reviewContinuation: grant, replayed: false };
}
let movingHeadPorts: PipelinePorts | null = null;

test("stop-after-fix, maxRounds 1: a final fix that writes a new head ends in needs_review with both heads and the last verdict, never completed (#1938)", async () => {
  const h = movingHeadHarness();
  movingHeadPorts = h.ports;
  await create(h.ports, BUDGET_STAGES({ to: "build", maxRounds: 1, ...STOP_AFTER_FIX }, null) as never);
  await tickPipelines([], h.ports);
  await failEveryCritique(h, 1, h.beforeBuildPass);

  const current = loadPipelines()[0]!;
  expect(current.state).toBe("needs_review");
  expect(current.closedAt).toBeNull();
  expect(current.cursor).toBeNull();
  expect(current.lastPassedCommit).toBe(REVIEW_HEADS[1]);
  expect(current.reviewPending).toMatchObject({
    stageId: "critique",
    attempt: 1,
    fixStageId: "build",
    fixAttempt: 2,
    reviewedHead: REVIEW_HEADS[0],
    currentHead: REVIEW_HEADS[1],
    verdict: "fail",
    findings: 1,
  });
  expect(current.stateDetail).toContain("last review failed");
  expect(current.stateDetail).toContain("unreviewed");
  /* No pass was recorded for the reviewer, and nothing completed. */
  const critiques = current.runs.find((run) => run.stageId === "critique")!.attempts;
  expect(critiques.map((attempt) => attempt.state)).toEqual(["failed"]);
  expect(critiques[0]!.reviewedHead).toBe(REVIEW_HEADS[0]);
  /* It survives a reload through the store unchanged. */
  expect(loadPipelines()[0]!.state).toBe("needs_review");
  /* Nothing ticks it forward on its own. */
  await tickPipelines([], h.ports);
  expect(loadPipelines()[0]!.state).toBe("needs_review");
  expect(loadPipelines()[0]!.runs.find((run) => run.stageId === "critique")!.attempts).toHaveLength(1);
  /* A pause and a resume bring it back to needs_review, still naming the head. */
  expect((await patchPipeline(current.id, { action: "pause" }, h.ports)).pipeline?.pausedState).toBe("needs_review");
  const resumed = await patchPipeline(current.id, { action: "resume" }, h.ports);
  expect(resumed.pipeline?.state).toBe("needs_review");
  expect(resumed.pipeline?.stateDetail).toBe(current.stateDetail);
});

test("stop-after-fix with no new head completes (#1938, #2187)", async () => {
  for (const edge of [STOP_AFTER_FIX]) {
    /* Round 1 writes H1 and the handoff fix leaves the tree at H1. */
    const h = movingHeadHarness(() => REVIEW_HEADS[0]!);
    await create(h.ports, BUDGET_STAGES({ to: "build", maxRounds: 1, ...edge }, null) as never);
    await tickPipelines([], h.ports);
    await failEveryCritique(h, 1, h.beforeBuildPass);

    const current = loadPipelines()[0]!;
    expect({ edge, state: current.state }).toEqual({ edge, state: "completed" });
    expect(current.stateDetail).toBe(FAIL_EDGE_BUDGET_SPENT_DETAIL);
    expect(current.reviewPending).toBeUndefined();
  }
});

test("stop-after-fix: a budget handoff recorded before reviewed heads existed is judged against the head its fix started from (#1938)", async () => {
  for (const [label, heads, expected] of [
    ["unchanged", () => REVIEW_HEADS[0]!, "completed"],
    ["moved", (round: number) => REVIEW_HEADS[round - 1]!, "needs_review"],
  ] as const) {
    const h = movingHeadHarness(heads);
    await create(h.ports, BUDGET_STAGES({ to: "build", maxRounds: 1, ...STOP_AFTER_FIX }, null) as never);
    await tickPipelines([], h.ports);
    await buildRound(h, "built v1");
    await critiqueRound(h, "fail", "round 1");
    /* The handoff as a pre-#1938 engine wrote it: no reviewed head. */
    const legacy = loadPipelines()[0]!;
    expect(legacy.cursor).toMatchObject({ stageId: "build", activatedBy: { budgetSpent: true } });
    delete legacy.runs.find((run) => run.stageId === "critique")!.attempts[0]!.reviewedHead;
    savePipelines([legacy]);
    await buildRound(h, "built v2");
    const current = loadPipelines()[0]!;
    expect({ label, state: current.state }).toEqual({ label, state: expected });
    expect(current.runs.find((run) => run.stageId === "critique")!.attempts[0]!.reviewedHead).toBe(REVIEW_HEADS[0]);
    if (expected === "needs_review") expect(current.reviewPending).toMatchObject({ reviewedHead: REVIEW_HEADS[0], currentHead: REVIEW_HEADS[1] });
  }
});

test("creation-time continuation refuses new grants and replays stored receipts", async () => {
  const h = movingHeadHarness();
  movingHeadPorts = h.ports;
  await create(h.ports, BUDGET_STAGES({ to: "build", maxRounds: 1, ...STOP_AFTER_FIX }, null) as never);
  await tickPipelines([], h.ports);
  await failEveryCritique(h, 1, h.beforeBuildPass);
  const parked = loadPipelines()[0]!;
  for (const rounds of [0, undefined, 10]) expect((await continueReview(parked, "invalid", rounds)).status).toBe(400);
  expect((await continueReview(parked, "stale", 1, "0".repeat(64))).code).toBe("STAGE_CHANGED");
  const refused = await continueReview(parked, "new", 1);
  expect(refused.status).toBe(409);
  expect(refused.error).toContain("cannot increase");
  expect(loadPipelines()[0]).toEqual(parked);
  const historic = await restoreHistoricReviewGrant(parked, "old", 1);
  const saved = loadPipelines()[0]!;
  expect((await continueReview(parked, "old", 1)).reviewContinuation).toEqual(historic.reviewContinuation);
  expect((await continueReview(parked, "old", 1)).replayed).toBe(true);
  expect((await continueReview(parked, "old", 2)).status).toBe(409);
  expect(loadPipelines()[0]).toEqual(saved);
  await critiqueRound(h, "pass", "approved head");
  expect(loadPipelines()[0]!.state).toBe("completed");
});

function acceptHead(pipeline: Pipeline, clientRequestId: string, expectedRevision = pipelineRevision(pipeline)) {
  return patchPipeline(pipeline.id, { action: "accept-head", clientRequestId, expectedRevision }, movingHeadPorts!);
}

test("accept-head completes a stop-after-fix lane along the review stage's null pass edge, records who accepted, replays and is refused outside needs_review (#2187)", async () => {
  const h = movingHeadHarness();
  movingHeadPorts = h.ports;
  await create(h.ports, BUDGET_STAGES({ to: "build", maxRounds: 1, ...STOP_AFTER_FIX }, null) as never);
  await tickPipelines([], h.ports);
  /* Refused while the lane still runs. */
  const running = loadPipelines()[0]!;
  const early = await acceptHead(running, "accept-early");
  expect(early.status).toBe(409);
  expect(early.error).toContain("requires a pipeline in needs_review");
  await failEveryCritique(h, 1, h.beforeBuildPass);
  const parked = loadPipelines()[0]!;
  expect(parked.state).toBe("needs_review");
  const revision = pipelineRevision(parked);

  expect((await patchPipeline(parked.id, { action: "accept-head", expectedRevision: revision }, h.ports)).status).toBe(400);
  expect((await acceptHead(parked, "accept-stale", "0".repeat(64))).code).toBe("STAGE_CHANGED");
  /* Another conversation is not the creator. */
  const stranger = await patchPipeline(parked.id, { action: "accept-head", clientRequestId: "accept-x", expectedRevision: revision }, h.ports, { kind: "agent", conversationId: "not-the-creator" } as never);
  expect(stranger.status).toBe(403);
  expect(loadPipelines()[0]!.state).toBe("needs_review");

  const accepted = await acceptHead(parked, "accept-1", revision);
  expect(accepted.error).toBeUndefined();
  expect(accepted.replayed).toBe(false);
  expect(accepted.reviewAcceptance).toMatchObject({
    clientRequestId: "accept-1",
    stageId: "critique",
    attempt: 1,
    fixStageId: "build",
    fixAttempt: 2,
    reviewedHead: REVIEW_HEADS[0],
    currentHead: REVIEW_HEADS[1],
    actor: { kind: "operator" },
  });
  const current = loadPipelines()[0]!;
  expect(current.state).toBe("completed");
  expect(current.cursor).toBeNull();
  expect(current.closedAt).not.toBeNull();
  expect(current.reviewPending).toBeUndefined();
  expect(current.stateDetail).toBe(FAIL_EDGE_BUDGET_SPENT_DETAIL);
  expect(current.lastPassedCommit).toBe(REVIEW_HEADS[1]);
  expect(current.reviewAcceptances).toHaveLength(1);
  /* No reviewer pass was invented for the accepted head. */
  expect(current.runs.find((run) => run.stageId === "critique")!.attempts.map((attempt) => attempt.state)).toEqual(["failed"]);

  const replay = await acceptHead(parked, "accept-1", revision);
  expect(replay.replayed).toBe(true);
  expect(replay.reviewAcceptance?.clientRequestId).toBe("accept-1");
  expect(pipelineRevision(loadPipelines()[0]!)).toBe(pipelineRevision(current));
  const late = await acceptHead(current, "accept-2");
  expect(late.status).toBe(409);
  expect(late.error).toContain("this one is completed");
  expect(loadPipelines()[0]!.reviewAcceptances).toHaveLength(1);
});

